}

input.new_string:
/**
 * Live, still-open issues whose due date has passed. Issues under an archived
 * project are excluded: restoring the project makes them eligible again.
 * Drives the overdue job.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issues)
    .innerJoin(projects, eq(projects.id, issues.projectId))
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          orgPredicate(projects.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          livePredicate(projects.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
    .all();

  return rows.map((row) => toIssue(row.issue));
}

